draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // draw a tree
  ctx.beginPath();
  ctx.moveTo(W/2, H/2);
  ctx.lineTo(W/2, H/2 - 50);
  ctx.stroke();

  // trunk
  ctx.beginPath();
  ctx.rect(W/2 - 10, H/2 - 50, 20, 50);
  ctx.stroke();

  // leaves
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 100, 50, 0, 2 * Math.PI);
  ctx.stroke();

  // legacy symbol (a book)
  ctx.beginPath();
  ctx.rect(W/2 - 25 + 20 * Math.sin(t), H/2 + 20, 50, 30);
  ctx.stroke();

  // lines to represent lasting
  for (let i = 0; i < 10; i++) {
    ctx.beginPath();
    ctx.moveTo(W/2 - 25 + 20 * Math.sin(t) + i * 5, H/2 + 50);
    ctx.lineTo(W/2 - 25 + 20 * Math.sin(t) + i * 5, H);
    ctx.stroke();
  }

  ctx.restore();
}
